type Callback = (payload: any) => void;

class EventBus {
    private subscribers: Map<string, Callback[]> = new Map();

    public subscribe(event: string, callback: Callback): void {
        if (!this.subscribers.has(event)) {
            this.subscribers.set(event, []);
        }
        this.subscribers.get(event)!.push(callback);
    }

    public publish(event: string, payload: any): void {
        if (this.subscribers.has(event)) {
            this.subscribers.get(event)!.forEach(callback => {
                try {
                    callback(payload);
                } catch (error) {
                    console.error(`Error in event bus subscriber for event "${event}":`, error);
                }
            });
        }
    }
}

export const eventBus = new EventBus();

import { randomUUID } from 'crypto';

export interface User {
    id: string;
    name: string;
    email: string;
}

const users = new Map<string, User>();

export const userService = {
    create: (data: { name: string; email: string }): User => {
        const id = randomUUID();
        const user = { ...data, id };
        users.set(id, user);
        return user;
    },

    getById: (id: string): User | undefined => {
        return users.get(id);
    },

    getAll: (): User[] => {
        return Array.from(users.values());
    },

    update: (id: string, data: Partial<Omit<User, 'id'>>): User | undefined => {
        const user = users.get(id);
        if (!user) {
            return undefined;
        }
        const updatedUser = { ...user, ...data };
        users.set(id, updatedUser);
        return updatedUser;
    },

    delete: (id: string): boolean => {
        return users.delete(id);
    }
};

import { randomUUID } from 'crypto';

export interface Project {
    id: string;
    name: string;
    description: string;
    memberIds: string[];
}

const projects = new Map<string, Project>();

export const projectService = {
    create: (data: { name: string; description: string; memberIds?: string[] }): Project => {
        const id = randomUUID();
        const project = { ...data, id, memberIds: data.memberIds || [] };
        projects.set(id, project);
        return project;
    },

    getById: (id: string): Project | undefined => {
        return projects.get(id);
    },

    getAll: (): Project[] => {
        return Array.from(projects.values());
    },

    update: (id: string, data: Partial<Omit<Project, 'id'>>): Project | undefined => {
        const project = projects.get(id);
        if (!project) {
            return undefined;
        }
        const updatedProject = { ...project, ...data };
        projects.set(id, updatedProject);
        return updatedProject;
    },

    delete: (id: string): boolean => {
        return projects.delete(id);
    },

    addMember: (projectId: string, userId: string): Project | undefined => {
        const project = projects.get(projectId);
        if (!project) {
            return undefined;
        }
        if (!project.memberIds.includes(userId)) {
            project.memberIds.push(userId);
        }
        projects.set(projectId, project);
        return project;
    },

    removeMember: (projectId: string, userId: string): Project | undefined => {
        const project = projects.get(projectId);
        if (!project) {
            return undefined;
        }
        project.memberIds = project.memberIds.filter(id => id !== userId);
        projects.set(projectId, project);
        return project;
    }
};

import { randomUUID } from 'crypto';
import { eventBus } from '../event-bus';

export type TaskStatus = 'todo' | 'in-progress' | 'done';

export interface Task {
    id: string;
    title: string;
    description: string;
    status: TaskStatus;
    assigneeId: string | null;
    projectId: string;
}

const tasks = new Map<string, Task>();
const validTransitions: Record<TaskStatus, TaskStatus[]> = {
    todo: ['in-progress'],
    'in-progress': ['done'],
    done: []
};

export const taskService = {
    create: (data: { title: string; description: string; projectId: string }): Task => {
        const id = randomUUID();
        const task: Task = { ...data, id, status: 'todo', assigneeId: null };
        tasks.set(id, task);
        return task;
    },

    getById: (id: string): Task | undefined => {
        return tasks.get(id);
    },

    getByProject: (projectId: string): Task[] => {
        return Array.from(tasks.values()).filter(task => task.projectId === projectId);
    },

    update: (id: string, data: Partial<Omit<Task, 'id' | 'status' | 'assigneeId' | 'projectId'>>): Task | undefined => {
        const task = tasks.get(id);
        if (!task) {
            return undefined;
        }
        const updatedTask = { ...task, ...data };
        tasks.set(id, updatedTask);
        return updatedTask;
    },

    delete: (id: string): boolean => {
        return tasks.delete(id);
    },

    assign: (id: string, assigneeId: string): Task | undefined => {
        const task = tasks.get(id);
        if (!task) {
            return undefined;
        }
        task.assigneeId = assigneeId;
        tasks.set(id, task);
        eventBus.publish('task.assigned', { 
            taskId: task.id, 
            taskTitle: task.title, 
            assigneeId: task.assigneeId 
        });
        return task;
    },

    changeStatus: (id: string, newStatus: TaskStatus): Task | undefined => {
        const task = tasks.get(id);
        if (!task) {
            return undefined;
        }
        const oldStatus = task.status;
        if (validTransitions[oldStatus].includes(newStatus)) {
            task.status = newStatus;
            tasks.set(id, task);
            eventBus.publish('task.statusChanged', { 
                taskId: task.id, 
                taskTitle: task.title, 
                assigneeId: task.assigneeId,
                oldStatus,
                newStatus 
            });
            return task;
        } 
        // Or throw an error, for now just returning undefined for invalid transition
        return undefined; 
    }
};

