import * as http from 'http';
import { URL } from 'url';

import { userService } from './services/user-service';
import { projectService } from './services/project-service';
import { taskService } from './services/task-service';
import { commentService } from './services/comment-service';
import { notificationService } from './services/notification-service';

// Helper to parse body
const parseBody = (req: http.IncomingMessage): Promise<any> => {
    return new Promise((resolve, reject) => {
        let body = '';
        req.on('data', chunk => body += chunk.toString());
        req.on('end', () => {
            try {
                resolve(JSON.parse(body));
            } catch (e) {
                reject(e);
            }
        });
    });
};

export const server = http.createServer(async (req, res) => {
    const url = new URL(req.url || '', `http://${req.headers.host}`);
    const method = req.method;
    const path = url.pathname;

    res.setHeader('Content-Type', 'application/json');

    try {
        // User routes
        if (path === '/users' && method === 'GET') {
            const users = userService.getAll();
            res.end(JSON.stringify(users));
        } else if (path === '/users' && method === 'POST') {
            const body = await parseBody(req);
            const user = userService.create(body);
            res.statusCode = 201;
            res.end(JSON.stringify(user));
        } else if (path.startsWith('/users/') && method === 'GET') {
            const id = path.split('/')[2];
            const user = userService.getById(id);
            if(user) res.end(JSON.stringify(user));
            else { res.statusCode = 404; res.end(JSON.stringify({ message: 'User not found' })); }
        }

        // Project routes
        else if (path === '/projects' && method === 'GET') {
            const projects = projectService.getAll();
            res.end(JSON.stringify(projects));
        } else if (path === '/projects' && method === 'POST') {
            const body = await parseBody(req);
            const project = projectService.create(body);
            res.statusCode = 201;
            res.end(JSON.stringify(project));
        }

        // Task routes
        else if (path === '/tasks' && method === 'GET') {
            const projectId = url.searchParams.get('projectId');
            if(projectId) {
                const tasks = taskService.getByProject(projectId);
                res.end(JSON.stringify(tasks));
            } else {
                res.statusCode = 400;
                res.end(JSON.stringify({ message: 'Missing projectId query parameter' }));
            }
        } else if (path === '/tasks' && method === 'POST') {
            const body = await parseBody(req);
            const task = taskService.create(body);
            res.statusCode = 201;
            res.end(JSON.stringify(task));
        }

        // Comment routes
        else if (path === '/comments' && method === 'POST') {
            const body = await parseBody(req);
            const { taskId, authorId } = body;

            // Fetch additional data required for the event payload
            const task = taskService.getById(taskId);
            const author = userService.getById(authorId);

            if (!task || !author) {
                res.statusCode = 404;
                res.end(JSON.stringify({ message: 'Task or Author not found' }));
                return;
            }

            const comment = commentService.create({ 
                ...body, 
                taskTitle: task.title,
                authorName: author.name,
                taskAssigneeId: task.assigneeId
            });
            res.statusCode = 201;
            res.end(JSON.stringify(comment));
        } else if (path.startsWith('/comments') && method === 'GET') {
            const taskId = url.searchParams.get('taskId');
            if (taskId) {
                const comments = commentService.getByTask(taskId);
                res.end(JSON.stringify(comments));
            } else {
                 res.statusCode = 400;
                res.end(JSON.stringify({ message: 'Missing taskId query parameter' }));
            }
        }

        // Notification routes
        else if (path === '/notifications' && method === 'GET') {
            const userId = url.searchParams.get('userId');
            if(userId) {
                const notifications = notificationService.getByUser(userId);
                res.end(JSON.stringify(notifications));
            } else {
                res.statusCode = 400;
                res.end(JSON.stringify({ message: 'Missing userId query parameter' }));
            }
        }

        // PUT /tasks/:id/status
        else if (path.match(/^\/tasks\/[^\/]+\/status$/) && method === 'PUT') {
            const id = path.split('/')[2];
            const { status } = await parseBody(req);
            const task = taskService.changeStatus(id, status);
            if (task) {
                res.end(JSON.stringify(task));
            } else {
                res.statusCode = 400;
                res.end(JSON.stringify({ message: 'Invalid status transition or task not found' }));
            }
        }

        // PUT /tasks/:id/assign
        else if (path.match(/^\/tasks\/[^\/]+\/assign$/) && method === 'PUT') {
            const id = path.split('/')[2];
            const { assigneeId } = await parseBody(req);
            const task = taskService.assign(id, assigneeId);
            if (task) {
                res.end(JSON.stringify(task));
            } else {
                res.statusCode = 404;
                res.end(JSON.stringify({ message: 'Task not found' }));
            }
        }

        // POST /projects/:id/members
        else if (path.match(/^\/projects\/[^\/]+\/members$/) && method === 'POST') {
            const projectId = path.split('/')[2];
            const { userId } = await parseBody(req);
            const project = projectService.addMember(projectId, userId);
            if (project) {
                res.end(JSON.stringify(project));
            } else {
                res.statusCode = 404;
                res.end(JSON.stringify({ message: 'Project not found' }));
            }
        } 

        else {
            res.statusCode = 404;
            res.end(JSON.stringify({ message: 'Not Found' }));
        }

    } catch (error) {
        console.error(error);
        res.statusCode = 500;
        res.end(JSON.stringify({ message: 'Internal Server Error' }));
    }
});

